package orders.authz_test

import data.orders.authz

test_read_same_tenant_allowed if {
	authz.allow with input as {
		"action": "read",
		"token": {"sub": "u42", "tenant": "acme", "scopes": ["orders:read"]},
		"order": {"id": "o1", "tenant": "acme"},
	}
}

test_refund_over_limit_denied if {
	not authz.allow with input as {
		"action": "refund",
		"amount": 900,
		"token": {
			"sub": "u17",
			"tenant": "acme",
			"scopes": ["orders:read", "orders:write"],
		},
		"order": {"id": "o1", "tenant": "acme"},
	}
		with data.roles as {"u17": ["refund_agent"]}
		with data.limits as {"u17": 500}
}
